create or replace function public.admin_publish_cycle_story(p_story_id uuid,p_title text,p_summary text,p_consent boolean,p_anonymized boolean,p_note text default null) returns void language plpgsql security definer set search_path=public as $$ declare v_actor uuid:=auth.uid(); begin if v_actor is null or not exists(select 1 from public.admin_roles where user_id=v_actor and role_key in ('super_admin','admin','outcome_reviewer')) then raise exception 'insufficient_privilege'; end if; if not p_consent then raise exception 'public_consent_required'; end if; if coalesce(trim(p_title),'')='' or coalesce(trim(p_summary),'')='' then raise exception 'content_required'; end if; update public.cycle_stories set title=p_title,summary=p_summary,consent_confirmed=true,anonymized=p_anonymized,status='approved',published_at=now(),updated_at=now() where id=p_story_id and status in ('draft','submitted','needs_info'); if not found then raise exception 'story_not_publishable'; end if; insert into public.audit_logs(actor_user_id,actor_role,action,subject_type,subject_id,note) values(v_actor,'outcome_reviewer','publish_cycle_story','cycle_story',p_story_id::text,p_note); end; $$; revoke all on function public.admin_publish_cycle_story(uuid,text,text,boolean,boolean,text) from public,anon; grant execute on function public.admin_publish_cycle_story(uuid,text,text,boolean,boolean,text) to authenticated; create or replace function public.admin_approve_esg_asset(p_asset_id uuid,p_title text,p_summary text,p_period_label text default null,p_note text default null) returns void language plpgsql security definer set search_path=public as $$ declare v_actor uuid:=auth.uid(); v_enterprise uuid; begin if v_actor is null or not exists(select 1 from public.admin_roles where user_id=v_actor and role_key in ('super_admin','admin','outcome_reviewer','enterprise_reviewer')) then raise exception 'insufficient_privilege'; end if; if coalesce(trim(p_title),'')='' or coalesce(trim(p_summary),'')='' then raise exception 'content_required'; end if; update public.enterprise_esg_assets set title=p_title,summary=p_summary,period_label=p_period_label,status='approved',updated_at=now() where id=p_asset_id and status in ('draft','submitted','needs_info') returning enterprise_id into v_enterprise; if not found then raise exception 'asset_not_approvable'; end if; insert into public.audit_logs(actor_user_id,actor_role,action,subject_type,subject_id,note) values(v_actor,'outcome_reviewer','approve_esg_asset','enterprise_esg_asset',p_asset_id::text,p_note); insert into public.user_notifications(recipient_user_id,kind,title,body,related_type,related_id) select eu.user_id,'esg_asset_ready','ESG 成果素材已完成','RCSCA 已完成一筆企業 ESG 成果素材，可至企業管理端查看。','enterprise_esg_asset',p_asset_id from public.enterprise_users eu where eu.enterprise_id=v_enterprise and not exists(select 1 from public.user_notifications n where n.recipient_user_id=eu.user_id and n.related_type='enterprise_esg_asset' and n.related_id=p_asset_id and n.kind='esg_asset_ready'); end; $$; revoke all on function public.admin_approve_esg_asset(uuid,text,text,text,text) from public,anon; grant execute on function public.admin_approve_esg_asset(uuid,text,text,text,text) to authenticated;
